import math

def max_nice_staircases(x):
    n = (-1 + math.isqrt(1 + 8 * x)) // 2
    return n

def main():
    t = int(input().strip())
    results = []
    for _ in range(t):
        x = int(input().strip())
        results.append(max_nice_staircases(x))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
